toolResult.textResultForLlm:
1. @page "/board"
2. @rendermode InteractiveServer
3. @inject ITaskService TaskService
4. 
5. <PageTitle>Kanban Board</PageTitle>
6. 
7. @if (loading)
8. {
9.     <p class="loading">Loading tasks...</p>
10. }
11. else if (errorMessage is not null)
12. {
13.     <div class="error-message">
14.         <p>@errorMessage</p>
15.         <button @onclick="LoadTasks">Retry</button>
16.     </div>
17. }
18. else
19. {
20.     <BoardStats Tasks="allTasks" />
21. 
22.     <div class="search-bar">
23.         <input type="text" placeholder="Search tasks by title..." @bind="searchTerm" @bind:event="oninput" />
24.     </div>
25. 
26.     <div class="kanban-board">
27.         <KanbanColumn Title="To Do"
28.                       Tasks="@FilteredTasks(StatusToDo)"
29.                       ShowMoveLeft="false"
30.                       ShowMoveRight="true"
31.                       OnMoveRight="@(task => MoveTask(task, StatusInProgress))"
32.                       OnTaskAdded="@(model => AddTask(model, StatusToDo))" />
33. 
34.         <KanbanColumn Title="In Progress"
35.                       Tasks="@FilteredTasks(StatusInProgress)"
36.                       ShowMoveLeft="true"
37.                       ShowMoveRight="true"
38.                       OnMoveLeft="@(task => MoveTask(task, StatusToDo))"
39.                       OnMoveRight="@(task => MoveTask(task, StatusDone))"
40.                       OnTaskAdded="@(model => AddTask(model, StatusInProgress))" />
41. 
42.         <KanbanColumn Title="Done"
43.                       Tasks="@FilteredTasks(StatusDone)"
44.                       ShowMoveLeft="true"
45.                       ShowMoveRight="false"
46.                       OnMoveLeft="@(task => MoveTask(task, StatusInProgress))"
47.                       OnTaskAdded="@(model => AddTask(model, StatusDone))" />
48.     </div>
49. }
50. 
51. @code {
52.     private const string StatusToDo = "To Do";
53.     private const string StatusInProgress = "In Progress";
54.     private const string StatusDone = "Done";
55. 
56.     private List<TaskItem> allTasks = new();
57.     private string searchTerm = string.Empty;
58.     private bool loading = true;
59.     private string? errorMessage;
60. 
61.     protected override async Task OnInitializedAsync()
62.     {
63.         await LoadTasks();
64.     }
65. 
66.     private async Task LoadTasks()
67.     {
68.         loading = true;
69.         errorMessage = null;
70. 
71.         try
72.         {
73.             allTasks = await TaskService.GetAllTasksAsync();
74.         }
75.         catch (Exception ex)
76.         {
77.             errorMessage = $"Failed to load tasks: {ex.Message}";
78.         }
79.         finally
80.         {
81.             loading = false;
82.         }
83.     }
84. 
